"use server"

import { revalidatePath } from "next/cache"
import { redirect } from "next/navigation"

// Mock database for user preferences
const userPreferences = new Map<string, boolean>()

// Initialize with a default user
userPreferences.set("currentUser", true) // true = notifications on

export async function toggleNotificationPreference() {
  const userId = "currentUser" // In a real app, get this from session
  const currentPreference = userPreferences.get(userId) ?? true

  // Toggle the preference
  userPreferences.set(userId, !currentPreference)

  // Revalidate the current path to refresh the page
  revalidatePath("/")

  // Return the new preference
  return { success: true, notificationsEnabled: !currentPreference }
}

export async function getNotificationPreference() {
  const userId = "currentUser" // In a real app, get this from session
  return userPreferences.get(userId) ?? true
}

