import { toggleNotificationPreference, getNotificationPreference } from "./actions"

export default async function Home() {
  const notificationsEnabled = await getNotificationPreference()

  return (
    <main>
      <h1>Settings</h1>
      <form action={toggleNotificationPreference}>
        <div>
          <label htmlFor="notifications">Enable Notifications</label>
          <input
            type="checkbox"
            id="notifications"
            name="notifications"
            checked={notificationsEnabled}
            onChange={() => {}}
          />
        </div>
        <button type="submit">Save</button>
      </form>
      <p>Current status: {notificationsEnabled ? "ON" : "OFF"}</p>
    </main>
  );
}

