import { toggleNotificationPreference, getNotificationPreference } from "./app/actions"

// Mock FormData for testing
const mockFormData = new FormData()

async function testToggle() {
  console.log("Testing notification toggle...")

  // Get initial preference
  const initialPref = await getNotificationPreference()
  console.log(`Initial preference: ${initialPref}`)

  // Toggle once
  const result1 = await toggleNotificationPreference(mockFormData)
  console.log(`After first toggle: ${result1.notificationsEnabled}`)

  // Get preference after first toggle
  const prefAfterFirst = await getNotificationPreference()
  console.log(`Preference after first toggle: ${prefAfterFirst}`)

  // Toggle again
  const result2 = await toggleNotificationPreference(mockFormData)
  console.log(`After second toggle: ${result2.notificationsEnabled}`)

  // Get preference after second toggle
  const prefAfterSecond = await getNotificationPreference()
  console.log(`Preference after second toggle: ${prefAfterSecond}`)

  console.log("Test completed!")
}

testToggle().catch(console.error)

